@sig trait ServiceEventOwner_Api {
  def id: Art.BridgeId
  def serviceLevels_Id : Art.PortId
  def serviceFacts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var serviceFacts: Vehicle_Mode_Coordinator.ServiceFacts = $

  def put_serviceFacts(value : Vehicle_Mode_Coordinator.ServiceFacts) : Unit = {
    Contract(
      Modifies(serviceFacts),
      Ensures(
        serviceFacts == value
      )
    )
    Spec {
      serviceFacts = value
    }

    Art.putValue(serviceFacts_Id, Vehicle_Mode_Coordinator.ServiceFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ServiceEventOwner_Initialization_Api (
  val id: Art.BridgeId,
  val serviceLevels_Id : Art.PortId,
  val serviceFacts_Id : Art.PortId) extends ServiceEventOwner_Api

@datatype class ServiceEventOwner_Operational_Api (
  val id: Art.BridgeId,
  val serviceLevels_Id : Art.PortId,
  val serviceFacts_Id : Art.PortId) extends ServiceEventOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var serviceLevels: Vehicle_Mode_Coordinator.ServiceLevels = $

  def get_serviceLevels() : Option[Vehicle_Mode_Coordinator.ServiceLevels] = {
    Contract(
      Ensures(
        Res == Some(serviceLevels)
      )
    )
    val value : Option[Vehicle_Mode_Coordinator.ServiceLevels] = Art.getValue(serviceLevels_Id) match {
      case Some(Vehicle_Mode_Coordinator.ServiceLevels_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port serviceLevels.  Expecting 'Vehicle_Mode_Coordinator.ServiceLevels_Payload' but received ${v}")
        None[Vehicle_Mode_Coordinator.ServiceLevels]()
      case _ => None[Vehicle_Mode_Coordinator.ServiceLevels]()
    }
    return value
  }
}
